// @ts-check
// Data-driven registry of public parcel services. Add a jurisdiction by adding an object here; no code changes.
//
// Entry shape:
//  id, coverage {state:'CA', countyFips?:'06037', county?:'Los Angeles County'}  (an entry with countyFips is tried before a statewide
//    entry; `county` is only used when a geocode has no FIPS, e.g. a browser-side Nominatim result)
//  searchRadiusM?: metres for the buffered search used when the geocoded point lies in the street, not in a parcel (default 40)
//  kind 'arcgis-feature'; url = the layer's /query endpoint
//  fields: map from our names to the service's field names:
//    apn, address, useType, yearBuilt, bedrooms, livingAreaSqft, units, lotAreaSqft?  (all but apn optional)
//    useCode, useDescription optional extras used for classification
//  useCodeScheme?: 'la-assessor' enables LA use-code rules in property_type classification
//  publisher, termsUrl, license
//  corsStatus: 'verified' (answered a cross-origin request from https://milessilverman.github.io with a matching
//    Access-Control-Allow-Origin, checked live) | 'not verified' (never tested: the browser registry skips these unless asked)
//  caveat?: why the service should not be used by default (not a parcel layer, or a stated use restriction); the provider skips it unless includeCaveated
//  termsNote?: StreetForge's `terms` text where it was a restriction note instead of a link (termsUrl is then the service page)
//  maxRecords?: the service's own page size (from StreetForge's list); fields.apn may be '' when the service has no usable parcel-number field
//
// Provenance of this file: the LA entry is copied from everyspace-demo index.html:19399-19400 (url + field names). The other CA
// entries are the county services listed in City Pretty app/data/parcel_services.json at commit ac7faf3, with only
// the APN and address fields (the rest were not mapped). Their termsUrl is City Pretty's `terms`, which is a
// service page, not a licence grant. Licences were not verified.
//
// 2026-11-27 extension (REUSE-B): the entries after `ALL OTHER SERVICES` are generated from StreetForge's assets/parcel-services.json
// (125 county and state ArcGIS REST services, itself taken from City Pretty's registry plus the LA County and Philadelphia layers),
// one entry per county FIPS (a service listing several counties becomes several entries with the same url) and one statewide entry
// per service that lists no counties (StreetForge streetforge2d.html:13668 rule: a state service only when truly statewide). The
// seven StreetForge entries for counties already listed above (06037 LA, 06029, 06073, 06059, 06065, 06071) are NOT duplicated:
// Everyspace's own entries win, and LA keeps its richer field map. For these entries only `fields.apn` is known (that is all
// StreetForge records); address, use, year, beds and living area are not mapped, so the registry provider reports them unavailable.
// Their `url` is StreetForge's layer url plus '/query'. `termsUrl` is StreetForge's `terms`. `license` is NOT_VERIFIED for all.
// The generated entries have `corsStatus: 'not verified'`: this build could only reach five hosts, none of them these services.

const NOT_VERIFIED = 'not verified 2026-11-24';

/** Build a generated entry (see the header). @param {string} id @param {{state:string, countyFips?:string}} coverage @param {string} url
 * @param {{apn:string}} fields @param {string} publisher @param {string} termsUrl @param {number|null} maxRecords @param {{caveat?:string, termsNote?:string}} [extra] */
const svc = (id, coverage, url, fields, publisher, termsUrl, maxRecords, extra = {}) => ({
  id, coverage, kind: /** @type {const} */ ('arcgis-feature'), url, fields, publisher, termsUrl, license: NOT_VERIFIED,
  corsStatus: /** @type {const} */ ('not verified'), ...(maxRecords ? { maxRecords } : {}), ...extra,
});

